<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_staff_or_admin();$errors=[];$editId=get_int('edit');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=post('action');$id=int_post('id');$name=post('name');$locked=in_array($id,[1,2,3],true);if($a==='save'){if($locked)$errors[]='สถานะหลัก 3 รายการถูกล็อกเพื่อให้ระบบยืม–คืนทำงานถูกต้อง';elseif($name==='')$errors[]='กรุณากรอกชื่อสถานะ';elseif((int)scalar('SELECT COUNT(*) FROM tbl_devices_status WHERE s_name=? AND s_id<>?',[$name,$id]))$errors[]='มีสถานะนี้แล้ว';else{try{if($id)execute_sql('UPDATE tbl_devices_status SET s_name=? WHERE s_id=?',[$name,$id]);else execute_sql('INSERT INTO tbl_devices_status(s_name) VALUES(?)',[$name]);flash('success',$id?'แก้ไขสถานะเรียบร้อย':'เพิ่มสถานะเรียบร้อย');redirect('staff/statuses.php');}catch(Throwable $e){$errors[]='บันทึกไม่สำเร็จ';}}}elseif($a==='delete'){if($locked)flash('danger','สถานะหลักของระบบไม่สามารถลบได้');elseif((int)scalar('SELECT COUNT(*) FROM tbl_devices WHERE ref_s_id=?',[$id]))flash('danger','ลบไม่ได้ เนื่องจากสถานะนี้ถูกใช้งานอยู่');else{execute_sql('DELETE FROM tbl_devices_status WHERE s_id=?',[$id]);flash('success','ลบสถานะเรียบร้อย');}redirect('staff/statuses.php');}}
$rows=fetch_all('SELECT s.*,COUNT(d.no) total FROM tbl_devices_status s LEFT JOIN tbl_devices d ON d.ref_s_id=s.s_id GROUP BY s.s_id,s.s_name ORDER BY s.s_id');$edit=$editId?fetch_one('SELECT * FROM tbl_devices_status WHERE s_id=?',[$editId]):null;render_header('สถานะครุภัณฑ์','statuses');
?>
<div class="page-intro"><div><h2>สถานะครุภัณฑ์</h2><p>พร้อมใช้งาน / กำลังถูกยืม / ชำรุด เป็นสถานะหลักที่ระบบควบคุมอัตโนมัติ</p></div></div><?php if($errors):?><div class="inline-alert danger"><b>!</b><span><?=implode('<br>',array_map('e',$errors))?></span></div><?php endif;?><div class="grid grid-3"><div class="card span-2"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>สถานะ</th><th>ครุภัณฑ์</th><th>ประเภท</th><th>จัดการ</th></tr></thead><tbody><?php foreach($rows as $r):$locked=in_array((int)$r['s_id'],[1,2,3],true);?><tr><td>#<?=e($r['s_id'])?></td><td><b><?=e($r['s_name'])?></b></td><td><?=e($r['total'])?> รายการ</td><td><span class="badge <?=$locked?'badge-primary':'badge-muted'?>"><?=$locked?'สถานะหลัก':'กำหนดเอง'?></span></td><td><?php if(!$locked):?><div class="btn-group"><a class="btn btn-soft btn-sm" href="?edit=<?=e($r['s_id'])?>">แก้ไข</a><form method="post" data-confirm="ลบสถานะนี้หรือไม่?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['s_id'])?>"><button class="btn btn-danger-soft btn-sm">ลบ</button></form></div><?php else:?><span class="muted">ล็อก</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header"><h3><?=$edit?'แก้ไขสถานะ':'เพิ่มสถานะเสริม'?></h3></div><div class="card-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['s_id']??0)?>"><div class="form-group"><label>ชื่อสถานะ</label><input class="form-control" name="name" maxlength="50" required value="<?=e($_POST['name']??($edit['s_name']??''))?>"></div><div class="form-actions mt-2"><?php if($edit):?><a class="btn btn-soft" href="<?=e(url('staff/statuses.php'))?>">ยกเลิก</a><?php endif;?><button class="btn btn-primary">บันทึก</button></div></form></div></div></div><?php render_footer();?>
